    assert is_strong_password("ab1!cdef") == False

def test_strong_password_missing_lower():
    assert is_strong_password("AB1!CDEF") == False

def test_strong_password_missing_digit():
    assert is_strong_password("Ab!!cdef") == False

def test_strong_password_missing_symbol():
    assert is_strong_password("Ab12cdef") == False

